<?php require_once 'config/config.php'; if(user()) redirect('dashboard.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $email=trim($_POST['email']??''); $pass=$_POST['password']??'';
$st=db()->prepare("SELECT u.*, rm.room_id, rm.role room_role FROM users u LEFT JOIN room_members rm ON rm.user_id=u.id AND rm.status='active' WHERE u.email=? LIMIT 1"); $st->execute([$email]); $u=$st->fetch();
if($u && password_verify($pass,$u['password_hash'])){ unset($u['password_hash']); $_SESSION['user']=$u; redirect($u['room_id']?'dashboard.php':'create-room.php'); } else $error='Invalid email or password.';}
?>
